const lockToken = String($execution.id) + ':' + Date.now();
let acquired = false;
try {
  acquired = (await client.set(lockKey, lockToken, { NX: true, PX: 900000 })) === 'OK';
} finally {
  await client.quit();
}
return [{ json: {
  lock_acquired: acquired,
  lock_key: lockKey,
  lock_token: lockToken,
  run_id: String($execution.id),
