  if (registry[maSp]) errors.push('DUPLICATE_MA_SP:' + maSp);
  registry[maSp] = {
    ma_sp: maSp,
    sheet_row: Number(r.ROW_NUMBER || index + 2),
    xml_group_id: String(r.XML_GROUP_ID || maSp).trim().toUpperCase(),
