    active: enabled(r.ACTIVE),
    aliases: tags(r.ALIASES || r.ALIAS),
    search_colors: tags(r.SEARCH_COLORS || r.MAU),
    search_styles: tags(r.SEARCH_STYLES || r.KIEU_DANG),
    search_materials: tags(r.SEARCH_MATERIALS),
