const normalizeUrl = (raw) => {
  let value = String(raw || '').trim().replace(/\.$/, '');
  if (!/^https:\/\//i.test(value)) throw new Error('url_must_use_https');
  const hash = value.indexOf('#'); if (hash >= 0) value = value.slice(0, hash);
  const q = value.indexOf('?'); if (q < 0) return value;
  const base = value.slice(0, q);
  const query = value.slice(q + 1).split('&').filter(Boolean).filter(part => {
    const key = part.split('=')[0].toLowerCase();
    return !key.startsWith('utm_') && key !== 'fbclid' && key !== 'gclid';
  }).sort();
  return query.length ? base + '?' + query.join('&') : base;
};

