const occasionRules = [
  {label:'ĐI LÀM',pattern:/di lam|cong so/}, {label:'ĐI TIỆC',pattern:/di tiec|du tiec|tiec nhe/},
  {label:'ĐI CHƠI',pattern:/di choi/}, {label:'DU LỊCH',pattern:/du lich/}, {label:'GẶP GỠ',pattern:/gap go/},
  {label:'CƯỚI HỎI',pattern:/cuoi hoi|dam cuoi|dam hoi/}, {label:'CHỤP ẢNH',pattern:/chup anh/}, {label:'HÀNG NGÀY',pattern:/hang ngay/}
];

const now = new Date().toISOString();
const profiles = [];
for (const reg of Object.values(registry)) {
  const candidateIds = unique([reg.xml_group_id, reg.ma_sp]);
  const groupId = candidateIds.find(id => groups.has(id));
  if (!groupId) continue;
  const group = groups.get(groupId);
  const first = group.items[0] || {};
  const rawTitle = text(first['g:title'] ?? first.title);
  const title = rawTitle.replace(/\s+-\s+(S|M|L|XL|XXL)$/i, '').trim();
  const descriptionXml = unicodeText(text(first['g:description'] ?? first.description));
  const link = text(first['g:link'] ?? first.link);
  const brandXml = text(first['g:brand'] ?? first.brand);
  const searchable = ascii([title, descriptionXml, ...group.attrs.map(attr => attr.value)].join(' '));
  let categoryAuto = 'OTHER';
  if (/ao dai/.test(searchable)) categoryAuto = 'AO_DAI';
  else if (/combo.*3|ba mon/.test(searchable) || reg.ma_sp.startsWith('CB')) categoryAuto = 'COMBO_3_MON';
  else if (/set quan/.test(searchable) || reg.ma_sp.startsWith('SQ')) categoryAuto = 'SET_QUAN';
  else if (/set vay/.test(searchable) || reg.ma_sp.startsWith('SV')) categoryAuto = 'SET_VAY';
  else if (/chan vay/.test(searchable)) categoryAuto = 'CHAN_VAY';
  else if (/\bvay\b|\bdam\b/.test(searchable)) categoryAuto = 'VAY';
  else if (/\bao\b/.test(searchable)) categoryAuto = 'AO';
  else if (/\bquan\b/.test(searchable)) categoryAuto = 'QUAN';
  const ruleAuto = categoryAuto === 'COMBO_3_MON' ? 'CB' : categoryAuto === 'SET_QUAN' ? 'SQ' : categoryAuto === 'SET_VAY' ? 'SV' : 'DIRECT';
  const ruleType = reg.rule_type || ruleAuto;
  const category = reg.category || categoryAuto;

  const colorResult = parseColors(descriptionXml, group.attrs, title, reg.color_override);
  const materialResult = extractMaterialComponents(descriptionXml, category, reg.material_override, reg.material_components_override);
  const styleResult = extractStyles(descriptionXml, reg.style_override);
  const silhouettesAuto = unique(matchLabels(searchable, silhouetteRules));
  const occasionsAuto = unique(matchLabels(searchable, occasionRules));
  const warnings = unique([
    ...(colorResult.primary.length ? [] : ['COLOR_NOT_FOUND']),
    ...materialResult.warnings,
    ...(styleResult.warning ? [styleResult.warning] : [])
  ]);
  const aliases = merge(reg.aliases, [title, groupId]);
  const searchColors = colorResult.primary;
  const searchStyles = styleResult.styles;
  const searchMaterials = materialResult.flat;
  const searchSilhouettes = merge(reg.search_silhouettes, silhouettesAuto);
  const searchOccasions = merge(reg.search_occasions, occasionsAuto);

  const urls = [];
  for (const raw of group.images) { try { urls.push(normalizeUrl(raw)); } catch (_) {} }
  const images = [...new Set(urls)].sort();
  const primaryImages = new Set([...group.primaryImages].map(raw => { try { return normalizeUrl(raw); } catch (_) { return ''; } }).filter(Boolean));
  const sizes = unique(group.attrs.filter(attr => ascii(attr.label).trim() === 'size').map(attr => attr.value));
  const classifications = unique(group.attrs.filter(attr => ascii(attr.label).includes('phan loai')).map(attr => attr.value));
  let confidence = 0;
  if (categoryAuto !== 'OTHER') confidence += 0.25;
  if (materialResult.flat.length) confidence += 0.30;
  if (styleResult.styles.length) confidence += 0.15;
  if (silhouettesAuto.length) confidence += 0.10;
  if (occasionsAuto.length) confidence += 0.10;
  if (colorResult.primary.length) confidence += 0.10;
  confidence = Number(confidence.toFixed(2));
  const hardWarnings = warnings.filter(value => value === 'MATERIAL_NOT_FOUND' || value === 'MATERIAL_COMPONENT_AMBIGUOUS');
  const reviewStatus = categoryAuto === 'OTHER' || hardWarnings.length || confidence < 0.55 ? 'NEED_REVIEW' : 'AUTO_OK';
  const materialXml = materialResult.summary;
  const sourceHash = crypto.createHash('sha256').update(JSON.stringify({
    extraction_version: EXTRACTION_VERSION, groupId, title, descriptionXml, link, images,
    color_primary: colorResult.primary, color_detail: colorResult.detail,
    material_components: materialResult.components, styles: styleResult.styles
  })).digest('hex');
  const xmlUpdatedAt = reg.source_hash === sourceHash && reg.xml_updated_at ? reg.xml_updated_at : now;
  profiles.push({
    reg, group_id: groupId, title, description_xml: descriptionXml, material_xml: materialXml,
    material_components: materialResult.components, color_primary: colorResult.primary,
    color_detail: colorResult.detail, style_primary: styleResult.styles[0] || '',
    style_secondary: styleResult.styles[1] || '', style_scores: styleResult.scores,
    extraction_warnings: warnings, extraction_version: EXTRACTION_VERSION,
    product_link: link, brand_xml: brandXml, images, primary_images: [...primaryImages], sizes, classifications,
    rule_type: ruleType, category, aliases, search_colors: searchColors, search_styles: searchStyles,
    search_materials: searchMaterials, search_silhouettes: searchSilhouettes, search_occasions: searchOccasions,
    auto_confidence: confidence, review_status: reviewStatus, source_hash: sourceHash, xml_updated_at: xmlUpdatedAt
  });
}

const data = [{
  range: 'product_registry!Q1:AH1', majorDimension: 'ROWS',
  values: [[
    'XML_TITLE','DESCRIPTION_XML','MATERIAL_XML','XML_LINK','XML_IMAGE_URLS','AUTO_CONFIDENCE','REVIEW_STATUS','SOURCE_HASH','XML_UPDATED_AT',
    'COLOR_OVERRIDE','STYLE_OVERRIDE','MATERIAL_COMPONENTS_OVERRIDE','COLOR_PRIMARY','COLOR_DETAIL','MATERIAL_COMPONENTS_JSON',
    'STYLE_PRIMARY','STYLE_SECONDARY','EXTRACTION_WARNINGS'
  ]]
}];
for (const profile of profiles) {
  const row = Number(profile.reg.sheet_row);
  if (!Number.isInteger(row) || row < 2) continue;
  data.push({range:'product_registry!B' + row, majorDimension:'ROWS', values:[[profile.group_id]]});
  data.push({range:'product_registry!E' + row + ':F' + row, majorDimension:'ROWS', values:[[profile.rule_type,profile.category]]});
  data.push({range:'product_registry!J' + row + ':Y' + row, majorDimension:'ROWS', values:[[
    profile.aliases.join(' | '), profile.search_colors.join(' | '), profile.search_styles.join(' | '),
    profile.search_materials.join(' | '), profile.search_silhouettes.join(' | '), profile.search_occasions.join(' | '),
    now, profile.title, profile.description_xml, profile.material_xml, profile.product_link,
    profile.images.slice(0, 8).join(' | '), profile.auto_confidence, profile.review_status, profile.source_hash, profile.xml_updated_at
  ]]});
  data.push({range:'product_registry!AC' + row + ':AH' + row, majorDimension:'ROWS', values:[[
    profile.color_primary.join(' | '), profile.color_detail.join(' | '), JSON.stringify(profile.material_components),
    profile.style_primary, profile.style_secondary, profile.extraction_warnings.join(' | ')
  ]]});
}
return [{json:{
  ...input, profiles, extraction_version: EXTRACTION_VERSION,
  profile_count: profiles.length, review_count: profiles.filter(p => p.review_status === 'NEED_REVIEW').length,
  should_write_registry: Number(run.shard_index || 0) === 0,
  sheet_request_body: {valueInputOption:'RAW',includeValuesInResponse:false,data}
}}];

const crypto = require('crypto');
const source = $input.first().json || {};
const labels = {AO_DAI:'ÁO DÀI',AO:'ÁO',CHAN_VAY:'CHÂN VÁY',QUAN:'QUẦN',VAY:'VÁY',PHU_KIEN:'PHỤ KIỆN',LOT:'LÓT'};
const primary = category => category === 'SET_QUAN' ? ['AO','QUAN'] : category === 'SET_VAY' ? ['AO','CHAN_VAY'] : category === 'COMBO_3_MON' ? ['AO','CHAN_VAY','QUAN'] : category === 'AO_DAI' ? ['AO_DAI','QUAN'] : category === 'CHAN_VAY' ? ['CHAN_VAY'] : category === 'VAY' ? ['VAY'] : category === 'AO' ? ['AO'] : category === 'QUAN' ? ['QUAN'] : [];
const unique = values => [...new Set((values || []).map(value => String(value || '').trim().toUpperCase()).filter(Boolean))];
const profiles = (source.profiles || []).map(profile => {
  const components = JSON.parse(JSON.stringify(profile.material_components || {}));
  const lining = unique(components.LOT || []);
  const misplacedMain = lining.filter(value => !value.includes('LÓT'));
  if (misplacedMain.length) {
    components.LOT = lining.filter(value => value.includes('LÓT'));
    for (const key of primary(profile.category)) components[key] = unique([...(components[key] || []), ...misplacedMain]);
    if (!components.LOT.length) delete components.LOT;
  }
  const ordered = {};
  for (const key of ['AO_DAI','AO','CHAN_VAY','QUAN','VAY','PHU_KIEN','LOT']) if ((components[key] || []).length) ordered[key] = unique(components[key]);
  const flat = unique(Object.values(ordered).flat());
  const summary = Object.entries(ordered).map(([key,values]) => (labels[key] || key) + ': ' + values.join(' | ')).join('; ');
  const warnings = unique((profile.extraction_warnings || []).filter(value => value !== 'MATERIAL_COMPONENT_AMBIGUOUS' || !flat.length));
  const hardWarnings = warnings.filter(value => value === 'MATERIAL_NOT_FOUND' || value === 'MATERIAL_COMPONENT_AMBIGUOUS');
  const reviewStatus = profile.category === 'OTHER' || hardWarnings.length || Number(profile.auto_confidence || 0) < 0.55 ? 'NEED_REVIEW' : 'AUTO_OK';
  const sourceHash = crypto.createHash('sha256').update(JSON.stringify({base:profile.source_hash,material_components:ordered,normalizer:'2.0.1'})).digest('hex');
  return {...profile,material_components:ordered,search_materials:flat,material_xml:summary,extraction_warnings:warnings,review_status:reviewStatus,source_hash:sourceHash};
});
const data = source.sheet_request_body?.data || [];
for (const profile of profiles) {
  const row = Number(profile.reg?.sheet_row);
  if (!Number.isInteger(row) || row < 2) continue;
  const main = data.find(item => item.range === 'product_registry!J' + row + ':Y' + row);
  if (main?.values?.[0]) { main.values[0][3] = profile.search_materials.join(' | '); main.values[0][9] = profile.material_xml; main.values[0][13] = profile.review_status; main.values[0][14] = profile.source_hash; }
  const derived = data.find(item => item.range === 'product_registry!AC' + row + ':AH' + row);
  if (derived?.values?.[0]) { derived.values[0][2] = JSON.stringify(profile.material_components); derived.values[0][5] = profile.extraction_warnings.join(' | '); }
}
return [{json:{...source,profiles,extraction_version:'2.0.1-structured-vi',review_count:profiles.filter(profile => profile.review_status === 'NEED_REVIEW').length}}];

const { createClient } = require('redis');
const lock = $('Acquire Registry Sync Lock').first().json;
const client = createClient({ url: $env.REDIS_URL || 'redis://redis:6379' });
await client.connect();
let released = 0;
try {
  released = await client.eval("if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end", { keys: [lock.lock_key], arguments: [lock.lock_token] });
} finally { await client.quit(); }
return [{ json: { ...$input.first().json, lock_released: released === 1 } }];

